
const $=s=>document.querySelector(s);const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let scene=0,market='서원시장',dish='미역국',variant=0,chosen=[0,0,0],sort='price',cartAdded=false;const titles=['주변 시장 메뉴','시장별 메뉴','메뉴와 재료','레시피 보기','재료 상품 선택','담기 완료'];const dishes=['미역국','제육볶음','어묵탕','떡볶이','오징어볶음','고등어조림','소불고기','갈비찜'];const markets=[['서원시장','244m',[0,1,2,3,4,5,6,7]],['명동시장','824m',[4,2,5,1]],['길동시장','1.2km',[7,6,0]]];
const groups=[{name:'소고기 · 국거리 100g',img:'beef',offers:[{name:'국내산 소고기',store:'형래네 고기가게',price:1500,old:2500,stock:6},{name:'국내산 소고기',store:'엘리스 고기가게',price:1800,old:3000,stock:4}]},{name:'건미역 · 20g',img:'seaweed',offers:[{name:'국내산 건미역',store:'쉬고싶은 야채가게',price:1200,old:2000,stock:4},{name:'국내산 건미역',store:'성민이네 야채가게',price:1500,old:2500,stock:5}]},{name:'다진 마늘 · 50g',img:'garlic',offers:[{name:'국내산 다진 마늘',store:'성민이네 야채가게',price:800,old:1000,stock:5},{name:'다진 마늘',store:'홍길이네 야채가게',price:1000,old:1500,stock:7}]}];
const variants=['소고기 미역국','바지락 미역국','가자미 미역국'];function mealName(){return dish==='미역국'?variants[variant]:dish}const money=n=>n.toLocaleString('ko-KR');function totals(){return groups.reduce((t,g,i)=>{const o=g.offers[chosen[i]];return {price:t.price+o.price,old:t.old+o.old}}, {price:0,old:0})}function toast(t){$('.toast').textContent=t;$('.toast').classList.remove('hidden');setTimeout(()=>$('.toast').classList.add('hidden'),2200)}function go(n){scene=n;render()}function grid(ids){return '<div class="dish-grid">'+ids.map(i=>`<button class="dish" data-dish="${i}"><img src="assets/dish${i}.png" alt="${dishes[i]}"><p>${dishes[i]}</p></button>`).join('')+'</div>'}function action(text,fn){$('#action').classList.remove('hidden');$('#content').classList.add('has-action');$('#action').innerHTML=`<button class="primary">${text}</button>`;$('#action button').onclick=fn}
function render(){const c=$('#content');c.classList.remove('has-action');$('#action').classList.add('hidden');$('.head b').textContent=scene===3?'레시피':scene===4?'재료 고르기':scene===5?'장바구니 담기':'시장한끼';$('.steps').innerHTML=titles.map((t,i)=>`<button data-scene="${i}" class="${scene===i?'on':''}">0${i+1}　${t}</button>`).join('');document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>go(+b.dataset.scene));
if(scene===0){c.innerHTML=`<p class="eyebrow">가까운 시장의 재료로</p><h1>오늘은 무엇을 먹을까요?</h1><p class="intro">메뉴를 고르면 필요한 재료를 모아드려요.</p><input class="meal-search" placeholder="먹고 싶은 메뉴 검색" aria-label="메뉴 검색"><div id="market-menus">${markets.map((m,i)=>`<section data-market-block="${i}"><div class="market-line"><button data-market="${i}">${m[0]}　›</button><span>${m[1]}</span></div>${grid(m[2])}</section>`).join('')}</div>`;c.querySelector('input').oninput=e=>{const q=e.target.value.trim();c.querySelectorAll('[data-dish]').forEach(b=>b.hidden=!dishes[+b.dataset.dish].includes(q))};document.querySelectorAll('[data-market]').forEach(b=>b.onclick=()=>{market=markets[+b.dataset.market][0];go(1)});}
if(scene===1){const m=markets.find(m=>m[0]===market)||markets[0];c.innerHTML=`<p class="eyebrow">${m[1]} 거리의 시장</p><h1>${market}에서 한 끼</h1><p class="intro">메뉴를 선택해 재료와 레시피를 확인하세요.</p><div style="margin-top:28px">${grid(m[2])}</div>`}
if(scene===2){const names=dish==='미역국'?variants:[dish];c.innerHTML=`<p class="eyebrow">${market} · 시장한끼</p><h1>${dish} 한 끼, 어떠세요?</h1><p class="intro">레시피를 살펴보거나 재료를 바로 골라보세요.</p>${names.map((n,i)=>`<article class="meal-card"><div class="meal-card-top"><h2>${n}</h2><button class="recipe-link" data-recipe="${i}">레시피 보기 ↗</button></div><p class="likes">♡ ${100-i*6}명이 관심을 보였어요</p><p class="ingredients-copy">${dish==='미역국'?['소고기','바지락','가자미'][i]+' · 건미역 · 다진 마늘 · 참기름':'메뉴에 필요한 재료를 확인해보세요'}</p><button class="bundle" data-bundle="${i}">필요한 재료 한 번에 고르기</button></article>`).join('')}`;document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{variant=+b.dataset.recipe;go(3)});document.querySelectorAll('[data-bundle]').forEach(b=>b.onclick=()=>{variant=+b.dataset.bundle;go(4)})}
if(scene===3){const recipe=dish==='미역국';c.innerHTML=`<p class="eyebrow">${market} · 레시피</p><h1>${mealName()}</h1><div class="recipe-meta"><span>2인분</span><span>조리 순서 확인</span></div><img class="recipe-hero" src="assets/${recipe?'soup':'dish'+dishes.indexOf(dish)}.png" alt="${mealName()}"><h2>필요한 재료</h2><p class="intro">${recipe?'건미역 20g · 소고기 100g · 다진 마늘 · 참기름 · 국간장 · 물':'선택한 메뉴의 재료와 조리법은 예시 준비 중입니다.'}</p><h2 style="margin-top:25px">조리 순서</h2>${(recipe?[['재료를 준비해주세요','소고기의 핏물을 키친타월로 닦고, 미역은 물에 불려주세요.'],['먹기 좋은 크기로 잘라주세요','불린 미역은 물기를 빼고 가위로 잘라주세요.'],['미역과 소고기를 볶아주세요','냄비에 참기름을 두르고 소고기와 미역을 볶아주세요.'],['물을 넣고 끓여주세요','물과 다진 마늘을 넣고 끓인 뒤 국간장으로 간을 맞춰주세요.']]:[['조리법 안내','이 시안의 상세 체험은 소고기 미역국을 기준으로 구성했습니다.']]).map((a,i)=>`<div class="recipe-step"><b>${i+1}</b><div><h3>${a[0]}</h3><p>${a[1]}</p></div></div>`).join('')}<p class="photo-credit">레시피는 시안용 예시입니다. 참기름·국간장 등 기본 양념은 재료 선택 목록에 포함하지 않았어요.</p>`;action('필요한 재료 고르기',()=>go(4))}
if(scene===4){if(dish!=='미역국'||variant!==0){c.innerHTML=`<h1>${mealName()}</h1><p class="intro">이 시안은 소고기 미역국의 재료 선택을 체험할 수 있어요.</p><button class="bundle" id="sample" style="margin-top:25px">소고기 미역국 재료 고르기</button>`;$('#sample').onclick=()=>{dish='미역국';variant=0;go(4)}}else{const t=totals();c.innerHTML=`<p class="eyebrow">${market} · ${mealName()}</p><h1>필요한 재료를 골라주세요</h1><p class="intro">재료마다 상품을 하나씩 선택해주세요.</p><div class="total"><div><span>총 상품 금액</span><strong>${money(t.price)}원</strong></div><p>정가 ${money(t.old)}원에서 ${money(t.old-t.price)}원을 아껴요</p></div><select class="sort" aria-label="상품 정렬"><option value="price" ${sort==='price'?'selected':''}>가격 낮은 순</option><option value="stock" ${sort==='stock'?'selected':''}>재고 많은 순</option></select>${groups.map((g,i)=>`<section><div class="ingredient-heading"><h2>${g.name}</h2><span>1개 선택</span></div><div class="offer-row">${g.offers.map((o,j)=>({...o,j})).sort((a,b)=>sort==='price'?a.price-b.price:b.stock-a.stock).map(o=>`<button class="offer ${chosen[i]===o.j?'selected':''}" data-group="${i}" data-offer="${o.j}" aria-pressed="${chosen[i]===o.j}"><img src="assets/${g.img}.png" alt="${o.name}"><span class="tick">${chosen[i]===o.j?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17.5 19 7.5"/></svg>':''}</span><div class="offer-body"><p>${o.name}</p><strong><em>${Math.round((1-o.price/o.old)*100)}%</em> ${money(o.price)}원</strong><small>${o.store}</small><small>재고 ${o.stock}개</small></div></button>`).join('')}</div></section>`).join('')}<p class="photo-credit">기본 양념은 별도 준비가 필요해요. 점포별로 상품을 수령하며, 실제 재고와 가격은 구매 시 확인해야 합니다.</p>`;c.querySelector('select').onchange=e=>{sort=e.target.value;const y=c.scrollTop;render();c.scrollTop=y};document.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>{const y=c.scrollTop;chosen[+b.dataset.group]=+b.dataset.offer;render();c.scrollTop=y});action('3개 재료 · '+money(t.price)+'원 담기',()=>{cartAdded=true;go(5)})}}
if(scene===5){const t=totals();c.innerHTML=`<div class="success"><div class="success-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17.5 19 7.5"/></svg></div><h1>장바구니에 담았어요</h1><p class="intro">소고기 미역국에 필요한 재료 3개</p><div class="cart-lines">${groups.map((g,i)=>`<div><span>${g.offers[chosen[i]].name}</span><b>${money(g.offers[chosen[i]].price)}원</b></div>`).join('')}<div><b>총 상품 금액</b><b>${money(t.price)}원</b></div></div><button class="secondary" id="continue">계속 메뉴 둘러보기</button></div>`;$('#continue').onclick=()=>go(0);action('장바구니 확인하기',()=>{c.innerHTML=`<p class="eyebrow">${market}</p><h1>장바구니</h1><p class="intro">소고기 미역국 재료 3개</p><div class="cart-lines">${groups.map((g,i)=>`<div><span>${g.offers[chosen[i]].name} · 1개</span><b>${money(g.offers[chosen[i]].price)}원</b></div>`).join('')}</div><div class="total"><div><span>총 상품 금액</span><strong>${money(t.price)}원</strong></div></div><p class="intro">결제와 실제 주문은 연결되지 않은 시안입니다.</p>`;action('메뉴로 돌아가기',()=>go(0))})}
document.querySelectorAll('[data-dish]').forEach(b=>b.onclick=()=>{dish=dishes[+b.dataset.dish];variant=0;go(2)});c.scrollTop=0}
$('.back').onclick=()=>{go([0,0,1,2,2,4][scene])};document.querySelectorAll('.nav button').forEach((b,i)=>{b.classList.toggle('active',i===0);b.onclick=()=>i===0?go(0):toast('시장한끼 흐름을 체험하는 시안입니다.')});document.querySelectorAll('.nav button')[0].lastChild.textContent='시장한끼';render();
